def lis_length(nums: list[int]) -> int:
    """
    Return the length of the longest strictly increasing subsequence of nums.
    Uses O(n log n) patience sorting approach.
    """
    if not nums:
        return 0

    # tails[i] will be the smallest tail element for an increasing subsequence of length i+1
    tails = []

    for num in nums:
        # Find the leftmost element in tails that is >= num
        # This is where num can replace to keep tails as small as possible
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num

    return len(tails)

