    cache = OrderedDict()
    results = []

    for op in ops:
        if op[0] == 'put':
            key, value = op[1], op[2]
            if key in cache:
                # Move to end (most recently used)
                cache.move_to_end(key)
                cache[key] = value
            else:
                cache[key] = value
                if len(cache) > capacity:
                    # Evict the least recently used (first item)
                    cache.popitem(last=False)
