def min_jumps(nums: list[int]) -> int:
    n = len(nums)
    if n == 1:
        return 0

    # If the first element is 0, we can't move anywhere
    if nums[0] == 0:
        return -1

    # BFS-like approach using greedy jump game logic
    # We track the farthest we can reach in the current number of jumps
    jumps = 0
    current_end = 0
    farthest = 0

    for i in range(n - 1):
        farthest = max(farthest, i + nums[i])

        if i == current_end:
            # We've reached the end of the current jump range
            if farthest <= i:
                # Can't move forward
                return -1
            jumps += 1
            current_end = farthest

            if current_end >= n - 1:
                break

    # Check if we can reach the last index
    if current_end >= n - 1:
        return jumps
    else:
        return -1

