def permutations_sorted(s: str) -> list[str]:
    if not s:
        return [""]

    # Use a set to track distinct permutations
    result = set()

    def backtrack(current: str, remaining: list[str]):
        if not remaining:
            result.add(current)
            return
        # Use a set to avoid trying the same character at the same position
        used = set()
        for i in range(len(remaining)):
            if remaining[i] in used:
                continue
            used.add(remaining[i])
            # Remove the i-th character from remaining
            new_remaining = remaining[:i] + remaining[i+1:]
            backtrack(current + remaining[i], new_remaining)

    backtrack("", list(s))
    return sorted(result)

