def kth_smallest_pair_distance(nums: list[int], k: int) -> int:
    nums.sort()
    n = len(nums)

    # Binary search on the answer
    # The distance can range from 0 to max(nums) - min(nums)
    lo, hi = 0, nums[-1] - nums[0]

    def count_pairs_with_distance_at_most(d):
        """Count number of pairs (i, j) with i < j and nums[j] - nums[i] <= d"""
        count = 0
        j = 0
        for i in range(n):
            if j < i:
                j = i
            while j < n and nums[j] - nums[i] <= d:
                j += 1
            # For this i, all indices from i+1 to j-1 satisfy the condition
            count += (j - i - 1)
        return count

    while lo < hi:
        mid = (lo + hi) // 2
        if count_pairs_with_distance_at_most(mid) < k:
            lo = mid + 1
        else:
            hi = mid

    return lo

def compress(s: str) -> str:
    if not s:
        return ""

    result = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            result.append(current_char)
            if count > 1:
                result.append(str(count))
            current_char = s[i]
            count = 1

    # Append the last run
    result.append(current_char)
    if count > 1:
        result.append(str(count))

    return ''.join(result)
